var S={u:null,menu:null,active:[],tables:null,type:null,table:null,name:'',draft:[],cat:null,order:null,adminTab:'panel',note:null,kitchenTimer:null,adminMenu:null,inventory:null,reportFrom:null,reportTo:null};
function esc(x){return String(x==null?'':x).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function eur(c){return (Number(c)/100).toFixed(2)+'€'}
async function api(u,o){o=o||{};o.headers=Object.assign({'Content-Type':'application/json'},o.headers||{});var r=await fetch(u,o),d=await r.json().catch(function(){return{}});if(!r.ok)throw Error(d.error||'Ndodhi një gabim.');return d}
function toast(t){var x=document.createElement('div');x.className='toast';x.textContent=t;document.body.appendChild(x);setTimeout(function(){x.remove()},2600)}
function head(sub){return '<header class="top"><div class="brand"><span class="brand-mark" aria-hidden="true">S</span><span class="brand-copy">SHARRI<small>'+esc(sub||'Sistemi i porosive')+'</small></span></div><div class="topRight"><button class="btn kitchen-nav" onclick="kitchen()">KUZHINA</button><span class="pill">'+esc(S.u.name)+' · '+(S.u.role==='ADMIN'?'Administrator':'Kamarier')+'</span><button class="btn" onclick="logout()">Dil</button></div></header>'}
function set(x){document.getElementById('app').innerHTML=x}
async function start(){var s=await api('/api/sesioni');if(!s.loggedIn)return login();S.u=s.user;if(S.u.role==='ADMIN')return admin();return waiter()}
function login(){set('<div class="login"><div class="card loginBox"><h1>SHARRI</h1><p>Kyçu në sistemin e porosive.</p><form onsubmit="doLogin(event)"><label>Përdoruesi</label><input id="user" required><label>Fjalëkalimi</label><input id="pass" type="password" required><button class="btn primary big" style="width:100%;margin-top:18px">Kyçu</button><div id="err"></div></form></div></div>')}
async function doLogin(e){e.preventDefault();try{var d=await api('/api/kycu',{method:'POST',body:JSON.stringify({username:document.getElementById('user').value,password:document.getElementById('pass').value})});S.u=d.user;S.u.role==='ADMIN'?admin():waiter()}catch(x){document.getElementById('err').innerHTML='<div class="error">'+esc(x.message)+'</div>'}}
async function logout(){await api('/api/dil',{method:'POST'});location.reload()}
async function waiter(){clearKitchenTimer();S.menu=await api('/api/menu');S.active=await api('/api/aktive');S.tables=await api('/api/tavolinat');renderWaiter()}
function clearKitchenTimer(){if(S.kitchenTimer){clearInterval(S.kitchenTimer);S.kitchenTimer=null}}
function home(){clearKitchenTimer();if(S.u&&S.u.role==='ADMIN')admin();else waiter()}
function renderWaiter(){
 var t=S.active.filter(x=>x.table_number),n=S.active.filter(x=>x.order_type==='EMER'),z=S.active.filter(x=>x.order_type==='ME_VETI'||x.order_type==='PER_KETU');
 set(head('Kamarier')+'<main class="main"><div class="hero"><div><h1>Porositë</h1><p><b>'+S.tables.occupied+' / 50</b> tavolina të zëna · '+S.active.length+' porosi aktive</p></div><button class="btn primary big" onclick="newOrder()">POROSI E RE</button></div>'+section('Tavolina të zëna',t,'TAVOLINË')+section('Porosi me emër',n,'EMËR')+section('Porosi pa tavolinë',z,'PA TAVOLINË')+tableLayout()+'</main>')
}
function tableLayout(){
 var tables=S.tables&&S.tables.tables||[];
 return '<section class="section table-layout-section"><div class="row table-layout-heading"><div><h2>Harta e tavolinave</h2><p class="muted">Prek tavolinën e lirë për të nisur porosinë, ose të zënën për ta hapur.</p></div><span class="tag">'+(S.tables.free||0)+' TË LIRA</span></div><div class="table-map">'+tables.map(function(t){var busy=!!t.order_id;return '<button type="button" class="table-tile '+(busy?'busy':'free')+'" onclick="tableAction('+(t.order_id||0)+','+t.number+')"><span class="table-tile-number">'+t.number+'</span><span class="table-tile-state">'+(busy?'ZËNË':'E LIRË')+'</span>'+(busy?'<span class="table-tile-total">'+eur(t.total_cents)+'</span>':'<span class="table-tile-cta">+ Porosi</span>')+'</button>'}).join('')+'</div></section>';
}
function tableAction(orderId,number){if(orderId)return openOrder(orderId);S.type='TAVOLINE';S.table=number;S.name='';S.draft=[];S.cat=null;renderDraft()}
function section(title,a,label){
 var h='<div class="section"><h2>'+title+'</h2>';
 if(!a.length)return h+'<div class="empty">Nuk ka porosi aktive.</div></div>';
 return h+'<div class="grid">'+a.map(function(o){
  var where=o.table_number?'Tavolina '+o.table_number:(o.custom_identifier||(o.order_type==='ME_VETI'?'Me veti':'Për këtu'));
  var pending=o.cancellation_request_status==='PENDING';
  return '<article class="card order" onclick="openOrder('+o.id+')"><div class="order-tags"><span class="tag">'+label+'</span>'+(pending?'<span class="tag cancel-pending">ANULIM NË PRITJE</span>':'')+'</div><h3>'+esc(where)+'</h3><div class="money">'+eur(o.total_cents)+'</div><p class="muted">'+o.item_count+' produkte · '+tm(o.opened_at)+'</p></article>'
 }).join('')+'</div></div>'
}
function newOrder(){set(head('Porosi e re')+'<main class="main"><div class="hero"><div><h1>Porosi e re</h1><p>Zgjidhni ku i përket porosia.</p></div><button class="btn" onclick="waiter()">Kthehu</button></div><div class="choices"><button class="choice" onclick="choose(\'TAVOLINE\')"><strong>Tavolinë</strong><small>Numri nga 1 deri në 50.</small></button><button class="choice" onclick="choose(\'EMER\')"><strong>Me emër</strong><small>Kur e dini emrin ose identifikuesin.</small></button><button class="choice" onclick="choose(\'ME_VETI\')"><strong>Me veti</strong><small>Vetëm kur porosia ka ushqim.</small></button><button class="choice" onclick="choose(\'PER_KETU\')"><strong>Për këtu</strong><small>Vetëm për porosi ushqimi.</small></button></div></main>')}
function choose(t){S.type=t;if(t==='TAVOLINE'){var a='';for(var i=1;i<=50;i++)a+='<button class="btn big" onclick="draftStart('+i+')">Tavolina '+i+'</button>';set(head('Zgjedhja e tavolinës')+'<main class="main"><div class="hero"><div><h1>Tavolinë</h1><p>Zgjidhni numrin.</p></div><button class="btn" onclick="newOrder()">Kthehu</button></div><div class="numbers">'+a+'</div></main>')}else if(t==='EMER'){set(head('Porosi me emër')+'<main class="main"><div class="card" style="padding:22px;max-width:600px"><h2>Emri / identifikuesi</h2><p class="muted">P.sh. Bastria, Enver, Nfund te Ora.</p><input id="cname" autofocus><div class="row" style="margin-top:15px"><button class="btn" onclick="newOrder()">Kthehu</button><button class="btn primary" onclick="namedStart()">Vazhdo</button></div></div></main>')}else draftStart(null)}
function namedStart(){var n=document.getElementById('cname').value.trim();if(!n)return toast('Shkruani emrin ose identifikuesin.');S.name=n;draftStart(null)}
function draftStart(t){S.table=t;S.name=S.type==='EMER'?S.name:'';S.draft=[];renderDraft()}
function kitchen(){
 clearKitchenTimer();
 set(head('Ekrani i kuzhinës')+'<main class="main kitchen-main"><div class="hero"><div><span class="public-eyebrow">Porositë për përgatitje</span><h1>Kuzhina</h1><p>Rifreskohet vetvetiu çdo 8 sekonda.</p></div><button class="btn" onclick="home()">Kthehu</button></div><div id="kitchen-board"><div class="empty">Duke ngarkuar porositë…</div></div></main>');
 refreshKitchen();
 S.kitchenTimer=setInterval(refreshKitchen,8000);
}
async function refreshKitchen(){
 var board=document.getElementById('kitchen-board');if(!board)return;
 try{var orders=await api('/api/kitchen');board.innerHTML=orders.length?'<div class="kitchen-grid">'+orders.map(function(o){var where=o.table_number?'Tavolina '+o.table_number:(o.custom_identifier||(o.order_type==='ME_VETI'?'Me veti':'Për këtu')),state=o.kitchen_status||'NEW',stateLabel=state==='NEW'?'E RE':state==='PREPARING'?'NË PËRGATITJE':'GATI';var next=state==='NEW'?'<button class="btn primary" onclick="setKitchenStatus('+o.id+',\'PREPARING\')">Nis përgatitjen</button>':state==='PREPARING'?'<button class="btn ok" onclick="setKitchenStatus('+o.id+',\'READY\')">Shëno gati</button>':'<button class="btn" onclick="setKitchenStatus('+o.id+',\'PREPARING\')">Kthe në përgatitje</button>';var items=o.items.map(function(x){return '<div class="kitchen-item"><span><b>'+x.quantity+' × '+esc(x.name)+'</b>'+(x.notes?'<small>'+esc(x.notes)+'</small>':'')+'</span><time>'+tm(x.created_at)+'</time></div>'}).join('');return '<article class="card kitchen-ticket '+state.toLowerCase()+'"><div class="kitchen-ticket-top"><div><span class="tag kitchen-status '+state.toLowerCase()+'">'+stateLabel+'</span><h2>'+esc(where)+'</h2><p class="muted">Porosia #'+o.order_number+' · '+esc(o.waiter_name||'')+'</p></div><div class="kitchen-elapsed">'+elapsed(o.opened_at)+'</div></div><div class="kitchen-items">'+items+'</div><div class="kitchen-ticket-actions">'+(state==='NEW'?'':state==='PREPARING'?'<button class="btn" onclick="setKitchenStatus('+o.id+',\'NEW\')">Rikthe si të re</button>':'<button class="btn" onclick="setKitchenStatus('+o.id+',\'NEW\')">Rikthe si të re</button>')+next+'</div></article>'}).join('')+'</div>':'<div class="empty">Nuk ka porosi ushqimi në radhë.</div>'}catch(e){board.innerHTML='<div class="empty">'+esc(e.message)+'</div>'}
}
function elapsed(value){var s=String(value||'');if(!s)return '—';if(!/[zZ]|[+-]\d\d:\d\d$/.test(s))s=s.replace(' ','T')+'Z';var mins=Math.max(0,Math.floor((Date.now()-new Date(s).getTime())/60000));return mins<1?'Tani':mins+' min';}
async function setKitchenStatus(id,status){try{await api('/api/kitchen/'+id,{method:'PATCH',body:JSON.stringify({status:status})});await refreshKitchen();toast(status==='READY'?'Porosia u shënua gati.':'Gjendja e kuzhinës u përditësua.')}catch(e){toast(e.message)}}
function productPhoto(p){if(p.image_path)return{src:p.image_path,packshot:p.kind==='PIJE'||p.kind==='KAFE'};var name=String(p.name||'').toLowerCase(),category=String(p.category_name||'').toLowerCase(),drink=category.indexOf('pije')!==-1||p.kind==='PIJE'||p.kind==='KAFE';if(name.indexOf('sniker')!==-1||name.indexOf('snicker')!==-1)return{src:'/images/snickers-cake.jpg'};if(name.indexOf('peje')!==-1||name.indexOf('peja')!==-1)return{src:'/images/birra-peja.jpg',packshot:true};if(name.indexOf('laqin')!==-1||name.indexOf('lacin')!==-1||name.indexOf('laçin')!==-1)return{src:'/images/laqin.png',packshot:true};if(name.indexOf('mokne')!==-1)return{src:'/images/uje-mokne.png',packshot:true};if(name.indexOf('laqko')!==-1||name.indexOf('lasko')!==-1||name.indexOf('laško')!==-1)return{src:'/images/lasko.jpg',packshot:true};if(name.indexOf('bavaria')!==-1)return{src:'/images/bavaria.jpg',packshot:true};if(name.indexOf('smirnof')!==-1||name.indexOf('smirnoff')!==-1)return{src:'/images/smirnoff-ice.jpg',packshot:true};if(name.indexOf('heniken')!==-1||name.indexOf('heineken')!==-1)return{src:'/images/heineken.jpg',packshot:true};if(name.indexOf('jager')!==-1||name.indexOf('jäger')!==-1)return{src:'/images/jagermeister.png',packshot:true};if(name.indexOf('multisola')!==-1||name.indexOf('multi sola')!==-1)return{src:'/images/multisola.jpg',packshot:true,tone:'multisola'};if(name.indexOf('ice tea')!==-1)return{src:'/images/ice-tea.png',packshot:true,tone:'ice-tea'};if(name.indexOf('fanta')!==-1)return{src:'/images/fanta.jpg',packshot:true};if(name.indexOf('schweeps')!==-1||name.indexOf('schweppes')!==-1)return{src:'/images/schwepps.png',packshot:true};if(name.indexOf('redbull')!==-1||name.indexOf('red bull')!==-1)return{src:'/images/red-bull.jpg',packshot:true};if(name.indexOf('golden eagle')!==-1)return{src:'/images/golden-eagle.jpg',packshot:true};if(name.indexOf('kokakolla')!==-1||name.indexOf('coca')!==-1)return{src:'/images/coca-cola.jpg'};if(name.indexOf('kafe')!==-1||name.indexOf('coffee')!==-1)return{src:'/images/coffee.jpg'};if(name.indexOf('qaj')!==-1||name.indexOf('çaj')!==-1)return{src:'/images/tea.jpg'};if(name.indexOf('qebap')!==-1)return{src:'/images/qebap.jpg'};if(name.indexOf('suxhuk')!==-1)return{src:'/images/suxhuk.jpg'};if(name.indexOf('qep')!==-1)return{src:'/images/qepa.jpg',packshot:true};if(name.indexOf('spec')!==-1)return{src:'/images/spec-i-pjekur.jpg'};if(name.indexOf('djath')!==-1)return{src:'/images/extra-djath.jpg',packshot:true};if(name.indexOf('domat')!==-1||name.indexOf('tranguj')!==-1||name.indexOf('trangull')!==-1)return{src:'/images/domat-tranguj.jpg'};if(name.indexOf('pule')!==-1)return{src:'/images/grilled-chicken.jpg'};if(name.indexOf('pica')!==-1)return{src:'/images/pizza.jpg'};if(name.indexOf('tuna')!==-1)return{src:'/images/tuna-sandwich.jpg'};if(name.indexOf('hamburger')!==-1&&name.indexOf('mish i bardh')!==-1)return{src:'/images/burger-mish-i-bardh.jpg'};if(name.indexOf('hamburger')!==-1)return{src:'/images/burger-sandwich.jpg'};if(name.indexOf('pomfrit')!==-1)return{src:'/images/pomfrit.jpg'};if(drink)return{src:'/images/juice.jpg'};if(p.kind==='EMBELSIRE'||category.indexOf('ëmbëlsira')!==-1)return{src:'/images/trileqe.jpg'};if(p.kind==='USHQIM'||category.indexOf('menze')!==-1)return{src:'/images/grill-platter.jpg'};return ''}
function productCard(p,action){var photo=productPhoto(p),tone=photo&&photo.tone?' '+photo.tone:'',out=p.stock_tracked&&Number(p.stock_quantity)<=0,stockNote=p.stock_tracked?(out?'<small class="stock-availability out">Pa stok</small>':Number(p.stock_quantity)<=Number(p.low_stock_threshold)?'<small class="stock-availability">Mbeten '+esc(p.stock_quantity)+' '+esc(p.stock_unit||'copë')+'</small>':''):'';return '<button class="product'+(photo?' has-photo':'')+(out?' out-of-stock':'')+'" '+(out?'disabled aria-disabled="true"':'onclick="'+action+'"')+'>'+(photo?'<img class="product-photo'+(photo.packshot?' packshot':'')+tone+'" src="'+esc(photo.src)+'" alt="Foto ilustruese: '+esc(p.name)+'" loading="lazy" decoding="async" onerror="this.remove()">':'')+'<span class="product-content"><strong>'+esc(p.name)+'</strong>'+stockNote+'<span class="product-price">'+eur(p.price_cents)+'</span></span></button>'}
function noteLabel(n){return '<span class="item-note">'+esc(n)+'</span>'}
function notePresets(){return ['Komplet','Komplet me majonez','Pa qepë','Pa domat','Pa tranguj','Pa majonez','Pa sallatë','Extra djath']}
function askNote(productName,current,apply){S.note={name:productName,apply:apply};document.body.insertAdjacentHTML('beforeend','<div class="modalBack" id="noteModal"><div class="modal"><h2>Shenim për '+esc(productName)+'</h2><p class="muted">Shenimi nuk e ndryshon çmimin. P.sh. “komplet me majonez, pa qepë”.</p><input id="noteInput" maxlength="200" value="'+esc(current||'')+'" placeholder="Komplet, pa qepë, pa majonez..."><div class="cats" style="margin:14px 0;flex-wrap:wrap">'+notePresets().map(function(t){return '<button class="btn" onclick="document.getElementById(\'noteInput\').value=this.textContent">'+esc(t)+'</button>'}).join('')+'</div><div class="row"><button class="btn" onclick="closeNote()">Kthehu</button><button class="btn primary" onclick="saveNote(false)">Ruaj shenimin</button><button class="btn red" onclick="saveNote(true)">Hiq shenimin</button></div></div></div>')}
function closeNote(){var el=document.getElementById('noteModal');if(el)el.remove()}
function saveNote(clear){var el=document.getElementById('noteInput'),v=clear?'':(el?el.value:'').trim(),n=S.note;closeNote();if(n&&typeof n.apply==='function')n.apply(v)}
function draftNote(i){var x=S.draft[i];if(!x)return;askNote(x.product.name,x.notes,function(v){x.notes=v;renderDraft()})}
function orderNote(id,itemId){var x=(S.order.items||[]).find(function(i){return i.id===itemId});if(!x)return;askNote(x.product_name_snapshot,x.notes,async function(v){try{await api('/api/porosi/'+id+'/shenim',{method:'PATCH',body:JSON.stringify({itemId:itemId,notes:v})});openOrder(id)}catch(e){toast(e.message)}})}
function renderDraft(){if(S.cat==null)S.cat=S.menu.categories[0].id;var ps=S.menu.products.filter(function(p){return p.category_id===S.cat}),sum=S.draft.reduce(function(a,x){return a+x.product.price_cents*x.qty},0);var cats=S.menu.categories.map(function(c){return '<button class="btn '+(c.id===S.cat?'primary':'')+'" onclick="S.cat='+c.id+';renderDraft()">'+esc(c.name)+'</button>'}).join('');var lines=S.draft.length?S.draft.map(function(x,i){return '<div class="line"><div class="row"><div class="item-detail"><b>'+esc(x.product.name)+'</b>'+(x.notes?noteLabel(x.notes):'')+'</div><b>'+eur(x.product.price_cents*x.qty)+'</b></div><div class="row"><div class="qty"><button aria-label="Zvogëlo sasinë" onclick="draftQty('+i+',-1)">−</button><b>'+x.qty+'</b><button aria-label="Rrit sasinë" onclick="draftQty('+i+',1)">+</button></div><span class="muted">'+eur(x.product.price_cents)+'</span></div><div class="row"><button class="btn note-btn" onclick="draftNote('+i+')">'+(x.notes?'Ndrysho shenimin':'Shenim (komplet, pa qepë...)')+'</button></div></div>'}).join(''):'<div class="empty">Shtoni produktet.</div>';set(head('Porosi')+'<main class="main"><div class="hero"><div><h1>'+esc(S.type==='TAVOLINE'?'Tavolina '+S.table:S.type==='EMER'?S.name:S.type==='ME_VETI'?'Me veti':'Për këtu')+'</h1><p>Shtoni produktet duke i prekur.</p></div><button class="btn" onclick="newOrder()">Anulo</button></div><div class="menu"><section><div class="cats">'+cats+'</div><div class="products">'+ps.map(function(p){return productCard(p,'addDraft('+p.id+')')}).join('')+'</div></section><aside class="card summary"><h2>Porosia</h2>'+lines+'<div class="total">'+eur(sum)+'</div><button class="btn primary big" style="width:100%" onclick="saveDraft()">Ruaj porosinë</button></aside></div></main>')}
function addDraft(id){var p=S.menu.products.find(function(x){return x.id===id}),x=S.draft.find(function(x){return x.product.id===id});if(!p||p.stock_tracked&&Number(p.stock_quantity)<=0)return toast('Ky produkt nuk ka stok.');if(x&&p.stock_tracked&&x.qty>=Number(p.stock_quantity))return toast('Nuk ka stok të mjaftueshëm.');x?x.qty++:S.draft.push({product:p,qty:1});renderDraft()}
function draftQty(i,d){var x=S.draft[i];if(d>0&&x.product.stock_tracked&&x.qty+d>Number(x.product.stock_quantity))return toast('Nuk ka stok të mjaftueshëm.');x.qty+=d;if(x.qty<1)S.draft.splice(i,1);renderDraft()}
async function saveDraft(){if(!S.draft.length)return toast('Shtoni të paktën një produkt.');var food=S.draft.some(function(x){return x.product.kind==='USHQIM'||x.product.kind==='EMBELSIRE'});if((S.type==='ME_VETI'||S.type==='PER_KETU')&&!food)return toast('Me veti dhe Për këtu lejohen vetëm kur porosia ka ushqim.');try{var d=await api('/api/porosi',{method:'POST',body:JSON.stringify({orderType:S.type,tableNumber:S.table,customIdentifier:S.name,items:S.draft.map(function(x){return{productId:x.product.id,quantity:x.qty,notes:x.notes||null}})})});toast('Porosia u ruajt.');openOrder(d.id)}catch(e){toast(e.message)}}
async function openOrder(id){S.order=await api('/api/porosi/'+id);renderOrder()}
function itemTimestamp(x,fullDate){var value=String(x.created_at||'');if(!value)return '<span class="item-time muted">Ora e regjistrimit nuk është e disponueshme</span>';return '<time class="item-time" datetime="'+esc(value)+'" title="'+esc(dt(value))+'">Shtuar në '+esc(fullDate?dt(value):tm(value))+'</time>'}
function eventPayload(e){var value=e.details;try{if(typeof value==='string')value=JSON.parse(value)}catch(_){return{}}if(typeof value==='string')return{value:value};return value&&typeof value==='object'?value:{}}
function activityText(e){var d=eventPayload(e),product=d.produkt||d.product||'produkti',items=Array.isArray(d.items)?d.items:[];if(e.event_type==='POROSI_U_KRIJUA'){var summary=items.map(function(x){return(x.product||x.produkt||'Produkt')+' × '+(x.quantity||1)+(x.notes?' ('+x.notes+')':'')}).join(', ');return'U krijua porosia'+(summary?' · '+summary:'')}if(e.event_type==='PRODUKT_U_SHTUA')return'U shtua '+product+' × '+(d.quantity||1);if(e.event_type==='PRODUKT_SASIA_NDRYSHUA')return'Sasia e '+product+' u ndryshua: '+d.from+' → '+d.to;if(e.event_type==='PRODUKT_U_HOQ')return'U hoq '+product+' ('+d.from+' → 0)';if(e.event_type==='SHENIM_U_NDRYSHUA')return d.to?'Shenimi i '+product+': “'+d.to+'”':'U hoq shenimi i '+product;if(e.event_type==='ANULIM_U_KERKUA')return'U kërkua anulimi i porosisë'+(d.arsye?' · '+d.arsye:'');if(e.event_type==='ANULIM_U_REFUZUA')return'Kërkesa për anulim u refuzua'+(d.shenim?' · '+d.shenim:'');if(e.event_type==='PAGESA_U_PERFUND'||e.event_type==='PAGESA_U_PERFUND_NGA_ADMIN'){var method=d.method||d.value||'';return'Pagesa u përfundua'+(method?' · '+({CASH:'Para të gatshme',CARD:'Kartelë',OTHER:'Tjetër'}[method]||method):'')}if(e.event_type==='NUK_U_PAGUA')return'Porosia u shënua si e papaguar';if(e.event_type==='POROSI_E_ANULUAR')return'Porosia u anulua'+(d.arsye?' · '+d.arsye:'');if(e.event_type==='KITCHEN_STATUS_CHANGED'){var kitchenState=function(v){return v==='NEW'?'e re':v==='PREPARING'?'në përgatitje':'gati'};return'Gjendja e kuzhinës u ndryshua: '+kitchenState(d.from)+' → '+kitchenState(d.to)}return String(e.event_type||'Veprim').replace(/_/g,' ').toLowerCase()}
function orderActivity(events,compact){if(!events||!events.length)return '<div class="empty">Nuk ka ndryshime të regjistruara.</div>';return '<div class="audit-list">'+events.map(function(e){var value=String(e.created_at||''),when=value?(compact?tm(value):dt(value)):'—';return '<div class="audit-entry"><time class="audit-time" datetime="'+esc(value)+'" title="'+esc(value?dt(value):'')+'">'+esc(when)+'</time><div class="audit-copy"><b>'+esc(activityText(e))+'</b><small>'+esc(e.actor_name||'Sistem')+'</small></div></div>'}).join('')+'</div>'}
function renderOrder(){
 var o=S.order;
 if(S.cat==null&&S.menu&&S.menu.categories.length)S.cat=S.menu.categories[0].id;
 var cancellation=o.cancellation_request||null,pending=cancellation&&cancellation.status==='PENDING',rejected=cancellation&&cancellation.status==='REJECTED',closed=o.status!=='ACTIVE',locked=pending||closed;
 var cats=S.menu.categories.map(function(c){return '<button class="btn '+(c.id===S.cat?'primary':'')+'" onclick="S.cat='+c.id+';orderMenu()">'+esc(c.name)+'</button>'}).join('');
 var notice=pending?'<div class="cancel-notice is-pending"><div><strong>Kërkesa për anulim është në pritje të miratimit.</strong><p><b>Arsyeja:</b> '+esc(cancellation.reason)+'</p><small>Porosia nuk do të anulohet pa miratimin e administratorit.</small></div><span class="tag cancel-pending">NË PRITJE</span></div>':rejected?'<div class="cancel-notice is-rejected"><div><strong>Kërkesa e fundit për anulim u refuzua.</strong><p><b>Arsyeja e kërkesës:</b> '+esc(cancellation.reason)+'</p>'+(cancellation.decision_note?'<small><b>Shënimi i administratorit:</b> '+esc(cancellation.decision_note)+'</small>':'')+'</div></div>':closed?'<div class="cancel-notice is-rejected"><div><strong>'+(o.status==='CANCELLED'?'Porosia është anuluar dhe ruajtur në historik.':'Porosia nuk është më aktive.')+'</strong>'+(cancellation&&cancellation.reason?'<p><b>Arsyeja:</b> '+esc(cancellation.reason)+'</p>':'')+'</div></div>':'';
 var lines=o.items.map(function(x){
  var controls=locked?'<div class="row"><span class="muted">Sasia: <b>'+x.quantity+'</b></span><span class="muted">'+eur(x.unit_price_cents)+' / copë</span></div>':'<div class="row"><div class="qty"><button aria-label="Zvogëlo sasinë" onclick="changeItem('+o.id+','+x.id+','+(x.quantity-1)+')">−</button><b>'+x.quantity+'</b><button aria-label="Rrit sasinë" onclick="changeItem('+o.id+','+x.id+','+(x.quantity+1)+')">+</button></div><span class="muted">'+eur(x.unit_price_cents)+'</span></div><div class="row"><button class="btn note-btn" onclick="orderNote('+o.id+','+x.id+')">'+(x.notes?'Ndrysho shenimin':'Shenim (komplet, pa qepë...)')+'</button></div>';
  return '<div class="line"><div class="row"><div class="item-detail"><b>'+esc(x.product_name_snapshot)+'</b>'+(x.notes?noteLabel(x.notes):'')+itemTimestamp(x,false)+'</div><b>'+eur(x.unit_price_cents*x.quantity)+'</b></div>'+controls+'</div>'
 }).join('');
 var where=o.table_number?'Tavolina '+o.table_number:(o.custom_identifier||(o.order_type==='ME_VETI'?'Me veti':'Për këtu'));
 var picker=locked?'<div class="empty cancel-lock">'+(pending?'Produktet dhe pagesa janë bllokuar derisa administratori ta shqyrtojë kërkesën.':'Porosia nuk mund të ndryshohet më.')+'</div>':'<div class="cats">'+cats+'</div><div id="orderProducts"></div>';
 var payment=locked?'<button class="btn big" style="width:100%" disabled>'+(pending?'Pagesa në pritje':o.status==='CANCELLED'?'Porosia e anuluar':'Porosia joaktive')+'</button>':'<button class="btn ok big" style="width:100%" onclick="pay('+o.id+')">PAGESA</button>';
 var printTools='<div class="receipt-actions"><span class="muted">Faturë termike:</span><button class="btn" onclick="printReceipt('+o.id+',58)">58 mm</button><button class="btn" onclick="printReceipt('+o.id+',80)">80 mm</button></div>';
 var cancel=locked?'':'<button class="btn red big cancel-order-btn" style="width:100%" onclick="askCancellation('+o.id+')">Kërko anulimin</button><p class="cancel-hint">Kërkesa kërkon miratimin e administratorit. Porosia nuk hiqet nga sistemi para miratimit.</p>';
 set(head(closed?'Detajet e porosisë':'Porosi aktive')+'<main class="main"><div class="hero"><div><h1>'+esc(where)+'</h1><p>Porosia #'+o.order_number+' · '+dt(o.opened_at)+(o.kitchen_status?' · Kuzhina: '+(o.kitchen_status==='NEW'?'E re':o.kitchen_status==='PREPARING'?'Në përgatitje':'Gati'):'')+'</p></div><button class="btn" onclick="waiter()">Kthehu</button></div>'+notice+'<div class="menu"><section>'+picker+'</section><aside class="card summary"><h2>Porosia #'+o.order_number+'</h2>'+lines+'<div class="total">'+eur(o.total_cents)+'</div>'+printTools+payment+cancel+'</aside></div><section class="section card audit-panel"><h2>Ndryshimet e porosisë</h2><p class="muted">Koha e regjistrimit shfaqet për çdo produkt dhe ndryshim.</p>'+orderActivity(o.events,true)+'</section></main>');
 if(!locked)orderMenu()
}
function orderMenu(){var ps=S.menu.products.filter(function(p){return p.category_id===S.cat}),el=document.getElementById('orderProducts');if(!el)return;el.innerHTML='<div class="products">'+ps.map(function(p){return productCard(p,'addOrder('+S.order.id+','+p.id+')')}).join('')+'</div>'}
function askCancellation(id){
 document.body.insertAdjacentHTML('beforeend','<div class="modalBack" id="cancelRequestModal"><div class="modal"><div class="row"><div><h2>Kërko anulimin e porosisë #'+S.order.order_number+'</h2><p class="muted">Porosia mbetet aktive derisa administratori ta miratojë. Arsyeja ruhet në historik.</p></div><button type="button" class="btn" onclick="document.getElementById(\'cancelRequestModal\').remove()">Mbyll</button></div><form onsubmit="sendCancellationRequest(event,'+id+')"><label for="cancelReason">Arsyeja e anulimit</label><textarea id="cancelReason" maxlength="500" required placeholder="Shkruani arsyen e anulimit..."></textarea><div class="row" style="margin-top:16px"><button type="button" class="btn" onclick="document.getElementById(\'cancelRequestModal\').remove()">Kthehu</button><button type="submit" class="btn red">Dërgo kërkesën</button></div></form></div></div>');
 var field=document.getElementById('cancelReason');if(field)field.focus()
}
async function sendCancellationRequest(e,id){
 e.preventDefault();var field=document.getElementById('cancelReason'),reason=field?field.value.trim():'';
 if(!reason){toast('Shkruani arsyen e anulimit.');if(field)field.focus();return}
 try{await api('/api/porosi/'+id+'/kerkese-anulim',{method:'POST',body:JSON.stringify({reason:reason})});var modal=document.getElementById('cancelRequestModal');if(modal)modal.remove();toast('Kërkesa për anulim iu dërgua administratorit.');await openOrder(id)}catch(error){toast(error.message)}
}
function reviewCancellation(id,decision){
 var accept=decision==='APPROVE',heading=accept?'Mirato anulimin e porosisë?':'Refuzo kërkesën për anulim?';
 var content=accept?'<p class="muted">Porosia do të hiqet nga porositë aktive, do të shënohet e anuluar dhe do të ruhet në historik bashkë me arsyen.</p>':'<p class="muted">Porosia do të mbetet aktive. Mund të shtoni një shënim për kamarierin.</p><label for="cancelDecisionNote">Shënimi i administratorit (opsional)</label><textarea id="cancelDecisionNote" maxlength="300" placeholder="Shënim për refuzimin..."></textarea>';
 var action=accept?'Prano dhe anulo':'Refuzo kërkesën';
 document.body.insertAdjacentHTML('beforeend','<div class="modalBack" id="cancelReviewModal"><div class="modal"><h2>'+heading+'</h2>'+content+'<div class="row" style="margin-top:17px"><button type="button" class="btn" onclick="document.getElementById(\'cancelReviewModal\').remove()">Kthehu</button><button type="button" class="btn '+(accept?'red':'primary')+'" onclick="sendCancellationReview('+id+',\''+decision+'\')">'+action+'</button></div></div></div>')
}
async function sendCancellationReview(id,decision){
 var note=document.getElementById('cancelDecisionNote'),path=decision==='APPROVE'?'prano':'refuzo';
 try{await api('/api/anulimet/'+id+'/'+path,{method:'POST',body:JSON.stringify({note:note?note.value.trim():''})});var modal=document.getElementById('cancelReviewModal');if(modal)modal.remove();toast(decision==='APPROVE'?'Porosia u anulua dhe u ruajt në historik.':'Kërkesa u refuzua; porosia mbetet aktive.');await adminTab()}catch(error){toast(error.message);await adminTab()}
}
async function addOrder(id,p){try{await api('/api/porosi/'+id+'/shto',{method:'POST',body:JSON.stringify({productId:p})});openOrder(id)}catch(e){toast(e.message)}}
async function changeItem(id,item,q){try{await api('/api/porosi/'+id+'/sasia',{method:'PATCH',body:JSON.stringify({itemId:item,quantity:q})});openOrder(id)}catch(e){toast(e.message)}}
function dt(x){var s=String(x||'');if(!s)return '-';if(!/[zZ]|[+-]\d\d:\d\d$/.test(s))s=s.replace(' ','T')+'Z';return new Date(s).toLocaleString('sq-AL',{timeZone:'Europe/Belgrade',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit'});}function tm(x){var s=String(x||'');if(!/[zZ]|[+-]\d\d:\d\d$/.test(s))s=s.replace(' ','T')+'Z';return new Date(s).toLocaleTimeString('sq-AL',{timeZone:'Europe/Belgrade',hour:'2-digit',minute:'2-digit'});}
S.historyFilter=S.historyFilter||'ALL';S.historyRows=S.historyRows||[];
function pay(id){document.body.insertAdjacentHTML('beforeend','<div class="modalBack" id="pay"><div class="modal"><h2>Përfundo pagesën</h2><p class="muted">Totali</p><div class="total">'+eur(S.order.total_cents)+'</div><div class="receipt-actions modal-receipt-actions"><span class="muted">Faturë</span><button class="btn" onclick="printReceipt('+id+',58)">58 mm</button><button class="btn" onclick="printReceipt('+id+',80)">80 mm</button></div><div class="choices"><button class="choice" onclick="finish('+id+',\'CASH\')"><strong>Para të gatshme</strong></button><button class="choice" onclick="finish('+id+',\'CARD\')"><strong>Kartelë</strong></button><button class="choice" onclick="finish('+id+',\'OTHER\')"><strong>Tjetër</strong></button></div><button class="btn red" style="margin-top:15px;width:100%" onclick="markUnpaid('+id+')">S&#x27;KA PAGU</button><button class="btn" style="margin-top:10px;width:100%" onclick="document.getElementById(\'pay\').remove()">Kthehu</button></div></div>')}
async function markUnpaid(id){try{await api('/api/porosi/'+id+'/mospagu',{method:'POST'});document.getElementById('pay').remove();toast('Porosia u shënua si e papaguar.');waiter()}catch(e){toast(e.message)}}
async function finish(id,m){try{await api('/api/porosi/'+id+'/pagesa',{method:'POST',body:JSON.stringify({method:m})});document.getElementById('pay').remove();toast('Pagesa u përfundua.');waiter()}catch(e){toast(e.message)}}
function printReceipt(id,width){
 width=Number(width)===58?58:80;var popup=window.open('','_blank','width=420,height=700');if(!popup)return toast('Lejo dritaren e re për të shtypur faturën.');
 popup.document.open();popup.document.write('<!doctype html><html><head><title>Fatura Sharri</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{margin:0;padding:0;background:#fff;color:#111;font:11px/1.42 Arial,sans-serif}body{box-sizing:border-box;width:'+width+'mm;padding:3mm;margin:0 auto}.receipt{text-align:center}.logo{font-family:Georgia,serif;font-size:27px;font-weight:900;letter-spacing:4px;margin:0 0 2px}.restaurant{font-size:10px;letter-spacing:1px;font-weight:700}.rule{border:0;border-top:1px dashed #111;margin:8px 0}.meta{display:flex;justify-content:space-between;gap:5px;text-align:left}.left{text-align:left}.item{display:flex;justify-content:space-between;gap:6px;text-align:left;margin:5px 0}.item-label{max-width:72%;overflow-wrap:anywhere}.note{font-size:9px;color:#333}.total-row{display:flex;justify-content:space-between;font-weight:900;font-size:15px;text-align:left}.muted{font-size:9px}.thanks{margin:10px 0 3px;font-weight:700}@page{size:'+width+'mm auto;margin:0}@media print{body{width:'+width+'mm;padding:3mm;margin:0}.no-print{display:none}}</style></head><body><div class="receipt">Duke përgatitur faturën…</div></body></html>');popup.document.close();
 api('/api/historiku/'+id).catch(function(){return api('/api/porosi/'+id)}).then(function(o){var where=o.table_number?'Tavolina '+o.table_number:(o.custom_identifier||(o.order_type==='ME_VETI'?'Me veti':o.order_type==='PER_KETU'?'Për këtu':'Pa tavolinë')),paid=o.payments&&o.payments.length?o.payments[o.payments.length-1]:null,method=paid?({CASH:'Para të gatshme',CARD:'Kartelë',OTHER:'Tjetër'}[paid.method]||paid.method):o.status==='UNPAID'?'Pa pagesë':o.status==='CANCELLED'?'Anuluar':'E hapur';var items=(o.items||[]).map(function(item){var name=item.product_name_snapshot||item.name||item.product_name||'Produkt';return '<div class="item"><span class="item-label">'+esc(item.quantity)+' × '+esc(name)+(item.notes?'<div class="note">'+esc(item.notes)+'</div>':'')+'</span><b>'+eur(item.quantity*item.unit_price_cents)+'</b></div>'}).join('');var html='<div class="logo">SHARRI</div><div class="restaurant">RESTORANT</div><hr class="rule"><div class="meta"><span>Porosia</span><b>#'+esc(o.order_number)+'</b></div><div class="meta"><span>Vendi</span><b>'+esc(where)+'</b></div><div class="meta"><span>Kamarieri</span><b>'+esc(o.waiter_name||'—')+'</b></div><div class="meta"><span>Data</span><b>'+esc(dt(o.opened_at))+'</b></div><div class="meta"><span>Statusi</span><b>'+esc(method)+'</b></div><hr class="rule"><div class="left"><b>PRODUKTI</b></div>'+items+'<hr class="rule"><div class="total-row"><span>TOTALI</span><span>'+eur(o.total_cents)+'</span></div><div class="thanks">Faleminderit që na vizituat!</div><div class="muted">Sharri · Ju mirëpresim përsëri</div></div><button class="no-print" onclick="window.print()">Shtyp faturën</button>';
 popup.document.querySelector('.receipt').outerHTML=html;popup.document.title='Fatura #'+o.order_number+' — Sharri';popup.focus();setTimeout(function(){popup.print()},350)
 }).catch(function(error){popup.document.body.innerHTML='<p>Fatura nuk u ngarkua: '+esc(error.message)+'</p>'})
}
async function admin(){var s=await api('/api/statistika');renderAdmin(s)}
function renderAdmin(s){set(head('Administratë')+'<main class="main"><div class="hero"><div><h1>Administrata</h1><p>Porosi, menu, stok, raporte dhe shërbimi.</p></div></div><div class="admin"><aside class="card side admin-side"><button class="'+(S.adminTab==='panel'?'active':'')+'" onclick="S.adminTab=\'panel\';admin()">Paneli</button><button class="'+(S.adminTab==='historiku'?'active':'')+'" onclick="S.adminTab=\'historiku\';adminTab()">Pagesat / Borxhet</button><button class="'+(S.adminTab==='anulimet'?'active':'')+'" onclick="S.adminTab=\'anulimet\';adminTab()">Kërkesat për anulim</button><button class="'+(S.adminTab==='gjurmet'?'active':'')+'" onclick="S.adminTab=\'gjurmet\';adminTab()">Gjurmët</button><div class="side-divider"></div><button class="'+(S.adminTab==='menu'?'active':'')+'" onclick="S.adminTab=\'menu\';adminTab()">Menuja</button><button class="'+(S.adminTab==='stock'?'active':'')+'" onclick="S.adminTab=\'stock\';adminTab()">Stoku</button><button class="'+(S.adminTab==='reports'?'active':'')+'" onclick="S.adminTab=\'reports\';adminTab()">Raportet</button><button class="'+(S.adminTab==='qr'?'active':'')+'" onclick="S.adminTab=\'qr\';adminTab()">QR Menu</button></aside><section id="adminContent"></section></div></main>');adminTab(s)}
async function adminTab(s){var el=document.getElementById('adminContent');if(!el)return;if(S.adminTab==='panel'){s=s||await api('/api/statistika');el.innerHTML='<div class="grid"><div class="card stat"><b>'+s.revenue+'</b><span class="muted">Të hyra sot</span></div><div class="card stat"><b>'+s.paid+'</b><span class="muted">Porosi të paguara</span></div><div class="card stat"><b>'+s.total+'</b><span class="muted">Porosi sot</span></div><div class="card stat"><b>'+s.cancelled+'</b><span class="muted">Të anuluara</span></div></div><div class="section card" style="padding:18px"><h2>Produktet më të shitura</h2><div class="tableWrap"><table class="table"><tr><th>Produkt</th><th>Sasia</th></tr>'+s.top.map(function(x){return '<tr><td>'+esc(x.name)+'</td><td>'+x.quantity+'</td></tr>'}).join('')+'</table></div></div>';return}if(S.adminTab==='historiku'){var rows=await api('/api/historiku');S.historyRows=rows;el.innerHTML='<div class="card" style="padding:18px"><div class="row"><div><h2>Pagesat dhe borxhet</h2><p class="muted">Të gjitha porositë, të paguarat dhe të papaguarat me datë, orë dhe produkte.</p></div><input id="search" style="max-width:320px" placeholder="Kërko porosi, tavolinë, emër..." oninput="searchHistory()"></div><div class="cats" style="margin:15px 0"><button class="btn '+(S.historyFilter==='ALL'?'primary':'')+'" onclick="setHistoryFilter(\'ALL\')">Të gjitha</button><button class="btn '+(S.historyFilter==='UNPAID'?'primary':'')+'" onclick="setHistoryFilter(\'UNPAID\')">Të papaguara</button><button class="btn '+(S.historyFilter==='PAID'?'primary':'')+'" onclick="setHistoryFilter(\'PAID\')">Të paguara</button><button class="btn '+(S.historyFilter==='CANCELLED'?'primary':'')+'" onclick="setHistoryFilter(\'CANCELLED\')">Të anuluara</button></div><div id="hist" class="tableWrap" style="margin-top:14px">'+hist(rows)+'</div></div>';return}if(S.adminTab==='anulimet'){var requests=await api('/api/anulimet');el.innerHTML='<div class="card cancellation-queue" style="padding:18px"><div><h2>Kërkesat për anulim</h2><p class="muted">Shqyrtoni arsyen për secilën porosi. Vetëm pas miratimit hiqet nga porositë aktive; historiku ruhet.</p></div>'+(requests.length?'<div class="cancellation-list">'+requests.map(function(x){var where=x.table_number?'Tavolina '+x.table_number:(x.custom_identifier||(x.order_type==='ME_VETI'?'Me veti':'Për këtu'));return '<article class="card cancellation-card"><div class="request-top"><div><span class="tag cancel-pending">NË PRITJE</span><h3>Porosia #'+x.order_number+' · '+esc(where)+'</h3></div><strong class="money">'+eur(x.total_cents)+'</strong></div><div class="request-meta"><span>Kërkoi <b>'+esc(x.requested_by_name||x.waiter_name)+'</b></span><time>'+dt(x.created_at)+'</time></div><div class="request-reason"><b>Arsyeja:</b> '+esc(x.reason)+'</div><div class="row request-actions"><button class="btn red" onclick="reviewCancellation('+x.id+',\'APPROVE\')">Prano dhe anulo</button><button class="btn" onclick="reviewCancellation('+x.id+',\'REJECT\')">Refuzo</button></div></article>'}).join('')+'</div>':'<div class="empty">Nuk ka kërkesa për anulim në pritje.</div>')+'</div>';return}if(S.adminTab==='menu'){await adminMenuTab(el);return}if(S.adminTab==='stock'){await adminStockTab(el);return}if(S.adminTab==='reports'){await adminReportsTab(el);return}if(S.adminTab==='qr'){adminQrTab(el);return}var a=await api('/api/audit');el.innerHTML='<div class="card" style="padding:18px"><h2>Gjurmët e sistemit</h2><div class="tableWrap"><table class="table"><tr><th>Ora</th><th>Përdoruesi</th><th>Veprimi</th><th>Objekti</th></tr>'+a.map(function(x){return '<tr><td>'+dt(x.created_at)+'</td><td>'+esc(x.actor_name||'Sistem')+'</td><td>'+esc(x.action)+'</td><td>'+esc(x.entity_type||'')+' '+(x.entity_id||'')+'</td></tr>'}).join('')+'</table></div></div>'}
function fileDataUrl(file){return new Promise(function(resolve,reject){var reader=new FileReader();reader.onload=function(){resolve(reader.result)};reader.onerror=reject;reader.readAsDataURL(file)})}
async function adminMenuTab(el){
 var data=await api('/api/admin/menu');S.adminMenu=data;
 var rows=data.products.map(function(p){var photo=productPhoto(p)||{},categoryOptions=data.categories.map(function(c){return '<option value="'+c.id+'" '+(c.id===p.category_id?'selected':'')+'>'+esc(c.name)+'</option>'}).join('');return '<tr><td><input id="menu-name-'+p.id+'" value="'+esc(p.name)+'" maxlength="100" aria-label="Emri i produktit"></td><td><div class="price-input"><input id="menu-price-'+p.id+'" type="number" min="0.01" step="0.01" value="'+(p.price_cents/100).toFixed(2)+'" aria-label="Çmimi në euro"><span>€</span></div></td><td><select id="menu-category-'+p.id+'" aria-label="Kategoria">'+categoryOptions+'</select></td><td><label class="active-toggle"><input id="menu-active-'+p.id+'" type="checkbox" '+(p.active?'checked':'')+'> Aktiv</label></td><td class="menu-photo-cell"><img id="menu-preview-'+p.id+'" class="menu-photo-preview" src="'+esc(photo.src||'/images/grill-platter.jpg')+'" alt="Foto '+esc(p.name)+'" onerror="this.src=\'/images/grill-platter.jpg\'"><input class="image-path-input" id="menu-image-path-'+p.id+'" value="'+esc(p.image_path||'')+'" placeholder="Foto standarde" aria-label="Rruga e fotos"><input class="menu-file-input" id="menu-file-'+p.id+'" type="file" accept="image/png,image/jpeg,image/webp" aria-label="Ngarko fotografi"><button class="btn upload-btn" type="button" onclick="uploadMenuPhoto('+p.id+')">Ngarko foto</button></td><td><input id="menu-order-'+p.id+'" type="number" min="0" max="9999" value="'+p.display_order+'" aria-label="Renditja"></td><td><button class="btn primary" type="button" onclick="saveMenuProduct('+p.id+')">Ruaj</button></td></tr>'}).join('');
 el.innerHTML='<div class="card menu-editor"><div class="admin-feature-heading"><div><h2>Menaxho menynë</h2><p class="muted">Përditëso çmimin, emrin, kategorinë, foton ose disponueshmërinë. Çmimet futen në euro.</p></div><span class="tag">'+data.products.length+' PRODUKTE</span></div><div class="tableWrap"><table class="table menu-editor-table"><thead><tr><th>Produkt</th><th>Çmimi</th><th>Kategoria</th><th>Gjendja</th><th>Fotoja</th><th>Renditja</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div></div>';
}
async function saveMenuProduct(id){
 var name=document.getElementById('menu-name-'+id).value.trim(),price=Number(document.getElementById('menu-price-'+id).value),category=Number(document.getElementById('menu-category-'+id).value),active=document.getElementById('menu-active-'+id).checked,displayOrder=Number(document.getElementById('menu-order-'+id).value),imagePath=document.getElementById('menu-image-path-'+id).value.trim();
 if(!name||!Number.isFinite(price)||price<=0)return toast('Shkruani emrin dhe çmimin e vlefshëm.');
 try{await api('/api/admin/menu/'+id,{method:'PATCH',body:JSON.stringify({name:name,price_cents:Math.round(price*100),category_id:category,active:active,display_order:displayOrder,image_path:imagePath})});toast('Produkti u ruajt.');await adminMenuTab(document.getElementById('adminContent'))}catch(e){toast(e.message)}
}
async function uploadMenuPhoto(id){
 var field=document.getElementById('menu-file-'+id),file=field&&field.files&&field.files[0];if(!file)return toast('Zgjidhni një fotografi fillimisht.');
 if(file.size>3*1024*1024)return toast('Fotografia duhet të jetë maksimumi 3 MB.');
 try{var dataUrl=await fileDataUrl(file),result=await api('/api/admin/menu-image',{method:'POST',body:JSON.stringify({dataUrl:dataUrl})});document.getElementById('menu-image-path-'+id).value=result.path;document.getElementById('menu-preview-'+id).src=result.path;toast('Fotoja u ngarkua. Shtyp “Ruaj” për ta lidhur me produktin.')}catch(e){toast(e.message)}
}
async function adminStockTab(el){
 var products=await api('/api/admin/inventory');S.inventory=products;var low=products.filter(function(p){return p.stock_tracked&&Number(p.stock_quantity)<=Number(p.low_stock_threshold)});
 var rows=products.map(function(p){var tracked=!!p.stock_tracked,units=['copë','shishe','porcion','kg','l','pako'],unit=units.includes(p.stock_unit)?p.stock_unit:'copë';return '<tr class="'+(tracked&&Number(p.stock_quantity)<=Number(p.low_stock_threshold)?'stock-low-row':'')+'"><td><b>'+esc(p.name)+'</b><small class="stock-category">'+esc(p.category_name)+'</small></td><td><label class="active-toggle"><input id="stock-track-'+p.id+'" type="checkbox" '+(tracked?'checked':'')+' onchange="toggleInventoryFields('+p.id+')"> Ndiq</label></td><td><input id="stock-quantity-'+p.id+'" type="number" min="0" step="0.1" value="'+(tracked?Number(p.stock_quantity):0)+'" '+(tracked?'':'disabled')+'></td><td><select id="stock-unit-'+p.id+'" '+(tracked?'':'disabled')+'>'+units.map(function(u){return '<option '+(unit===u?'selected':'')+'>'+u+'</option>'}).join('')+'</select></td><td><input id="stock-threshold-'+p.id+'" type="number" min="0" step="0.1" value="'+(tracked?Number(p.low_stock_threshold):5)+'" '+(tracked?'':'disabled')+'></td><td>'+(tracked?'<span class="tag '+(Number(p.stock_quantity)<=Number(p.low_stock_threshold)?'stock-alert':'stock-ok')+'">'+(Number(p.stock_quantity)<=Number(p.low_stock_threshold)?'STOK I ULËT':'NË RREGULL')+'</span>':'<span class="muted">Pa monitorim</span>')+'</td><td><button class="btn '+(tracked?'primary':'')+'" type="button" onclick="saveInventory('+p.id+')">'+(tracked?'Ruaj':'Nis monitorimin')+'</button></td></tr>'}).join('');
 el.innerHTML='<div class="card inventory-panel"><div class="admin-feature-heading"><div><h2>Stoku i produkteve</h2><p class="muted">Shitjet e produkteve të monitoruara e ulin stokun automatikisht. Vendos pragun për njoftim.</p></div><span class="tag '+(low.length?'stock-alert':'stock-ok')+'">'+low.length+' ME STOK TË ULËT</span></div>'+(low.length?'<div class="low-stock-banner"><b>Duhet rimbushur:</b> '+low.map(function(p){return esc(p.name)+' ('+esc(p.stock_quantity)+' '+esc(p.stock_unit)+')'}).join(' · ')+'</div>':'')+'<div class="tableWrap"><table class="table stock-table"><thead><tr><th>Produkti</th><th>Ndiq stokun</th><th>Sasia</th><th>Njësia</th><th>Pragu i ulët</th><th>Gjendja</th><th></th></tr></thead><tbody>'+rows+'</tbody></table></div><p class="stock-footnote">Stoku llogaritet për artikull të gatshëm (p.sh. shishe, porcion ose copë), jo për receta përbërësish.</p></div>';
}
function toggleInventoryFields(id){var enabled=document.getElementById('stock-track-'+id).checked;['quantity','unit','threshold'].forEach(function(field){var el=document.getElementById('stock-'+field+'-'+id);if(el)el.disabled=!enabled})}
async function saveInventory(id){
 var track=document.getElementById('stock-track-'+id).checked;
 try{if(!track){var current=(S.inventory||[]).find(function(p){return p.id===id});if(current&&current.stock_tracked)await api('/api/admin/inventory/'+id,{method:'DELETE'});toast('Monitorimi i stokut u përditësua.');return adminStockTab(document.getElementById('adminContent'))}
  var quantity=Number(document.getElementById('stock-quantity-'+id).value),unit=document.getElementById('stock-unit-'+id).value,threshold=Number(document.getElementById('stock-threshold-'+id).value);
  await api('/api/admin/inventory/'+id,{method:'PUT',body:JSON.stringify({quantity:quantity,unit:unit,low_stock_threshold:threshold})});toast('Stoku u ruajt.');await adminStockTab(document.getElementById('adminContent'))
 }catch(e){toast(e.message)}
}
function localDateString(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
async function adminReportsTab(el){
 var today=localDateString(new Date()),first=today.slice(0,8)+'01';if(!S.reportFrom)S.reportFrom=first;if(!S.reportTo)S.reportTo=today;
 el.innerHTML='<div class="card reports-panel"><div class="admin-feature-heading"><div><h2>Raportet e shitjeve</h2><p class="muted">Zgjidh periudhën për të krahasuar të hyrat, mënyrat e pagesës dhe produktet më të shitura.</p></div><a class="btn report-export" id="report-export" href="#">Eksporto CSV</a></div><div class="report-filters"><label>Prej <input type="date" id="report-from" value="'+esc(S.reportFrom)+'" onchange="S.reportFrom=this.value"></label><label>Deri <input type="date" id="report-to" value="'+esc(S.reportTo)+'" onchange="S.reportTo=this.value"></label><button class="btn" onclick="reportPreset(\'today\')">Sot</button><button class="btn" onclick="reportPreset(\'month\')">Këtë muaj</button><button class="btn primary" onclick="loadReports()">Shfaq raportin</button></div><div id="report-results"><div class="empty">Duke përgatitur raportin…</div></div></div>';
 await loadReports();
}
function reportPreset(preset){var today=localDateString(new Date()),from=today;if(preset==='month')from=today.slice(0,8)+'01';S.reportFrom=from;S.reportTo=today;var a=document.getElementById('report-from'),b=document.getElementById('report-to');if(a)a.value=from;if(b)b.value=today;loadReports()}
async function loadReports(){
 var out=document.getElementById('report-results'),from=document.getElementById('report-from'),to=document.getElementById('report-to');if(!out||!from||!to)return;S.reportFrom=from.value;S.reportTo=to.value;
 try{var data=await api('/api/admin/reports?'+new URLSearchParams({from:from.value,to:to.value})),exportLink=document.getElementById('report-export');if(exportLink)exportLink.href='/api/admin/reports.csv?'+new URLSearchParams({from:from.value,to:to.value});var max=Math.max(1,...data.days.map(function(x){return Number(String(x.revenue).replace(/[^0-9.]/g,''))}));var payments=data.payments.length?data.payments.map(function(p){var label={CASH:'Para të gatshme',CARD:'Kartelë',OTHER:'Tjetër'}[p.method]||p.method;return '<div class="report-payment-row"><span>'+esc(label)+'</span><b>'+esc(p.amount)+'</b><small>'+p.count+' pagesa</small></div>'}).join(''):'<div class="empty">Nuk ka pagesa në këtë periudhë.</div>';var days=data.days.length?data.days.map(function(d){var amount=Number(String(d.revenue).replace(/[^0-9.]/g,'')),width=Math.max(3,amount/max*100);return '<div class="report-day-row"><time>'+esc(d.day)+'</time><div class="report-bar-track"><span style="width:'+width+'%"></span></div><b>'+esc(d.revenue)+'</b><small>'+d.orders+' porosi</small></div>'}).join(''):'<div class="empty">Nuk ka shitje të paguara në këto data.</div>';var products=data.products.length?'<table class="table"><thead><tr><th>Produkti</th><th>Sasia</th><th>Të hyra</th></tr></thead><tbody>'+data.products.map(function(p){return '<tr><td>'+esc(p.name)+'</td><td>'+p.quantity+'</td><td>'+esc(p.revenue)+'</td></tr>'}).join('')+'</tbody></table>':'<div class="empty">Nuk ka produkte të shitura.</div>';out.innerHTML='<div class="grid report-stats"><div class="card stat"><b>'+esc(data.summary.revenue)+'</b><span class="muted">Të hyra</span></div><div class="card stat"><b>'+data.summary.paid_orders+'</b><span class="muted">Porosi të paguara</span></div><div class="card stat"><b>'+esc(data.summary.average_order)+'</b><span class="muted">Mesatarja e porosisë</span></div><div class="card stat"><b>'+esc(data.unpaid.total)+'</b><span class="muted">Borxhe · '+data.unpaid.count+' porosi</span></div></div><div class="reports-grid"><section class="card report-block"><h3>Pagesat sipas mënyrës</h3>'+payments+'</section><section class="card report-block"><h3>Produktet më të shitura</h3>'+products+'</section></div><section class="card report-block report-days"><h3>Shitjet ditore</h3>'+days+'</section><p class="muted report-caption">U anuluan '+data.cancelled+' porosi në periudhën e zgjedhur.</p>'}catch(e){out.innerHTML='<div class="empty error">'+esc(e.message)+'</div>'}
}
function adminQrTab(el){var base=location.origin;el.innerHTML='<div class="qr-admin-grid"><section class="card qr-card"><span class="public-eyebrow">Menuja e klientëve</span><h2>Menuja QR</h2><p class="muted">Klientët mund të skanojnë kodin për ta parë menynë aktuale në telefon. Ndryshimet në produktet aktive shfaqen automatikisht.</p><a class="btn primary" href="/menu" target="_blank" rel="noopener">Hap menynë publike</a><div class="qr-url"><span>Adresa publike</span><a href="/menu" target="_blank" rel="noopener">'+esc(base+'/menu')+'</a></div><p class="muted qr-note">Shtype kodin dhe vendose në tavolina. Printo nga shfletuesi për ta ruajtur si fletë.</p></section><section class="card qr-image-card"><img src="/api/admin/menu-qr.svg?t='+Date.now()+'" alt="Kodi QR i menusë"><a class="btn" href="/api/admin/menu-qr.svg" download="sharri-menu-qr.svg">Shkarko kodin QR</a></section></div>'}
function filteredHistory(a){var q=(document.getElementById('search')||{}).value||'';q=q.toLowerCase();return (a||[]).filter(function(x){if(S.historyFilter!=='ALL'&&x.status!==S.historyFilter)return false;if(!q)return true;return String(x.order_number).includes(q)||String(x.table_number||'').includes(q)||(x.custom_identifier||'').toLowerCase().includes(q)})}
function setHistoryFilter(f){S.historyFilter=f;document.getElementById('hist').innerHTML=hist(S.historyRows)}
async function searchHistory(){var q=document.getElementById('search').value;S.historyRows=await api('/api/historiku?'+new URLSearchParams({q:q}));document.getElementById('hist').innerHTML=hist(S.historyRows)}
function hist(a){a=filteredHistory(a);return a.length?'<table class="table"><tr><th>Porosia</th><th>Data / Ora</th><th>Vendndodhja</th><th>Kamarieri</th><th>Totali</th><th>Statusi</th><th>Veprimi</th></tr>'+a.map(function(x){var w=x.table_number?'Tavolina '+x.table_number:(x.custom_identifier||(x.order_type==='ME_VETI'?'Me veti':'Për këtu'));var when=x.status==='UNPAID'?x.unpaid_at:(x.completed_at||x.updated_at);var st=x.status==='PAID'?'Paguar':x.status==='UNPAID'?'Nuk ka paguar':'Anuluar';var act=x.status==='UNPAID'?'<button class="btn ok" onclick="event.stopPropagation();adminPay('+x.id+')">Shëno si paguar</button>':'—';return '<tr onclick="details('+x.id+')" style="cursor:pointer"><td>#'+x.order_number+'</td><td>'+dt(when)+'</td><td>'+esc(w)+'</td><td>'+esc(x.waiter_name)+'</td><td>'+eur(x.total_cents)+'</td><td>'+st+'</td><td>'+act+'</td></tr>'}).join('')+'</table>':'<div class="empty">Nuk u gjet asnjë porosi.</div>'}
function adminPay(id){document.body.insertAdjacentHTML('beforeend','<div class="modalBack" id="adminPay"><div class="modal"><h2>Regjistro pagesën</h2><p class="muted">Porosia e papaguar do të shënohet si e paguar tani.</p><div class="choices"><button class="choice" onclick="finishAdminPay('+id+',\'CASH\')"><strong>Para të gatshme</strong></button><button class="choice" onclick="finishAdminPay('+id+',\'CARD\')"><strong>Kartelë</strong></button><button class="choice" onclick="finishAdminPay('+id+',\'OTHER\')"><strong>Tjetër</strong></button></div><button class="btn" style="margin-top:15px;width:100%" onclick="document.getElementById(\'adminPay\').remove()">Kthehu</button></div></div>')}
async function finishAdminPay(id,m){try{await api('/api/porosi/'+id+'/paguaj',{method:'POST',body:JSON.stringify({method:m})});document.getElementById('adminPay').remove();toast('Pagesa u regjistrua.');S.historyFilter='UNPAID';admin()}catch(e){toast(e.message)}}
async function details(id){var o=await api('/api/historiku/'+id),w=o.table_number?'Tavolina '+o.table_number:(o.custom_identifier||(o.order_type==='ME_VETI'?'Me veti':'Për këtu')),paid=o.payments&&o.payments.length?o.payments[o.payments.length-1]:null;document.body.insertAdjacentHTML('beforeend','<div class="modalBack" id="detail"><div class="modal"><div class="row"><div><h2>Porosia #'+o.order_number+'</h2><p class="muted">'+esc(w)+' · '+esc(o.waiter_name)+'</p></div><button class="btn" onclick="document.getElementById(\'detail\').remove()">Mbyll</button></div><div class="section"><p><b>U hap:</b> '+dt(o.opened_at)+'</p><p><b>Statusi:</b> '+(o.status==='PAID'?'Paguar':o.status==='UNPAID'?'Nuk ka paguar':'Anuluar')+'</p>'+(o.unpaid_at?'<p><b>U shënua pa pagesë:</b> '+dt(o.unpaid_at)+'</p>':'')+(o.completed_at?'<p><b>U pagua / u përfundua:</b> '+dt(o.completed_at)+'</p>':'')+(paid?'<p><b>Mënyra e pagesës:</b> '+esc(paid.method)+'</p>':'')+'</div><h3>Produktet dhe koha e regjistrimit</h3><div>'+o.items.map(function(x){return '<div class="line"><div class="row"><div class="item-detail"><b>'+x.quantity+' × '+esc(x.product_name_snapshot)+'</b>'+(x.notes?noteLabel(x.notes):'')+itemTimestamp(x,true)+'</div><b>'+eur(x.quantity*x.unit_price_cents)+'</b></div></div>'}).join('')+'</div><div class="total">'+eur(o.total_cents)+'</div><div class="receipt-actions"><span class="muted">Faturë termike:</span><button class="btn" onclick="printReceipt('+o.id+',58)">58 mm</button><button class="btn" onclick="printReceipt('+o.id+',80)">80 mm</button></div><h3>Ndryshimet e porosisë</h3>'+orderActivity(o.events,false)+'</div></div>')}

window.addEventListener('error',function(e){if(e&&e.error)console.error(e.error);});
window.addEventListener('unhandledrejection',function(e){console.error(e.reason);});
start().catch(function(e){set('<div class="login"><div class="card loginBox"><h1>Gabim</h1><p class="error">'+esc(e.message)+'</p></div></div>')});
